    {
      "id": "E66b85f739dd153e7",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "No caso investigado, o procedimento de gestão de mudanças vigente no dia do acidente não abrangia mudanças em procedimentos, limitando-se a unidade, equipamentos, sistemas e pessoas, o que restringia o tratamento formal de alterações procedimentais.",
          "trechos": [
            "E66b85f739dd153e7:0:700"
          ],
          "condicoes": [
            "Referente ao procedimento de Management of Change vigente na data do acidente no FPSO Cidade de São Mateus"
          ],
          "limites": [
            "Achado específico do caso investigado",
            "Não demonstra, por si só, que toda gestão de mudanças em FPSOs tenha o mesmo escopo"
          ]
        },
        {
          "proposicao": "A inexistência de definição de procedimentos críticos para a unidade foi associada à não conclusão do processo de migração e atualização de procedimentos, enquanto auditoria interna e estudo de risco já apontavam necessidade de atualização documental e controle para evitar uso de documentos desatualizados.",
          "trechos": [
            "E66b85f739dd153e7:0:700",
            "E66b85f739dd153e7:700:1397"
          ],
          "condicoes": [
            "Contexto de migração de procedimentos iniciado em 2011",
            "Constatações baseadas em auditoria interna de 2012 e no Safety Case citado no relatório"
          ],
          "limites": [
            "Relação reconstruída a partir da investigação e de documentos internos mencionados",
            "Não estabelece critério normativo geral de quais procedimentos devem ser classificados como críticos"
          ]
        },
        {
          "proposicao": "Segundo o relatório, mudanças em procedimentos do sistema de gestão foram readequadas aos requisitos da BW e interferiram no gerenciamento de segurança operacional, ao mesmo tempo em que a alteração de operador da instalação só foi oficialmente comunicada à ANP anos depois do início das mudanças.",
          "trechos": [
            "E66b85f739dd153e7:1397:2096"
          ],
          "condicoes": [
            "No contexto da transição envolvendo Prosafe, BW e Petrobras no FPSO CDSM"
          ],
          "limites": [
            "Conclusão vinculada ao caso e ao foco regulatório do relatório",
            "Não permite generalizar que toda mudança societária produza o mesmo efeito operacional"
          ]
        }
      ]
    },
    {
      "id": "E1502117fd18ac61e",
      "pertinente": false,
      "tipo": "indeterminado",
      "achados": []
    },
    {
      "id": "Ed6f5fb05ed979b33",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "O resumo técnico recomenda que o processo de gerenciamento de mudanças seja reavaliado quando houver alteração de premissas, escopo, finalidade ou planejamento considerados.",
          "trechos": [
            "Ed6f5fb05ed979b33:0:698"
          ],
          "condicoes": [
            "Aplicável às mudanças cujas premissas, escopo, finalidade ou planejamento se alterem"
          ],
          "limites": [
            "Trata-se de recomendação derivada da investigação",
            "O trecho não detalha método de reavaliação nem critérios quantitativos"
          ]
        },
        {
          "proposicao": "É recomendado estabelecer procedimento escrito de passagem de serviço que assegure registro, acesso e conhecimento prévio de mudanças, isolamentos e condições operacionais relevantes para cada função antes da assunção do trabalho a bordo.",
          "trechos": [
            "Ed6f5fb05ed979b33:0:698"
          ],
          "condicoes": [
            "Antes de assumir o trabalho a bordo",
            "Para funções afetadas por mudanças, isolamentos e condições operacionais dos sistemas"
          ],
          "limites": [
            "Recomendação do relatório; não é apresentada no trecho como requisito legal autônomo",
            "O conteúdo mínimo citado não esgota todos os elementos possíveis de uma passagem de serviço"
          ]
        },
        {
          "proposicao": "O documento recomenda criar mecanismos para manter documentação técnica atualizada durante mudanças e garantir capacitação teórica e prática, com reciclagem periódica, para execução dos procedimentos de gerenciamento de mudanças; também recomenda aplicar gestão de mudanças de pessoas e tutoria antes da efetivação da mudança.",
          "trechos": [
            "Ed6f5fb05ed979b33:698:1394",
            "Ed6f5fb05ed979b33:1394:2094",
            "Ed6f5fb05ed979b33:2094:2345"
          ],
          "condicoes": [
            "Durante mudanças que afetem equipamentos, processos ou documentação",
            "Nos casos de redução, aumento, acúmulo de funções, entrada e saída de pessoas",
            "Antes da efetivação da mudança de pessoas"
          ],
          "limites": [
            "Recomendações sintéticas de resumo executivo",
            "O trecho não define conteúdo programático, carga horária, formato de tutoria ou critérios de competência"
          ]
        }
      ]
    },
    {
      "id": "E3dfa8ba0ae5476a8",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "No caso investigado, embora a ausência da posição de superintendente de marinha fosse conhecida pela equipe e houvesse fluxo formal para mudança de pessoal, não houve abertura de formulário de gestão de mudança por nenhum requisitante.",
          "trechos": [
            "E3dfa8ba0ae5476a8:0:693",
            "E3dfa8ba0ae5476a8:693:1391"
          ],
          "condicoes": [
            "No contexto do FPSO CDSM e do procedimento da BW para gerenciamento de mudança de pessoas"
          ],
          "limites": [
            "Achado específico do caso investigado",
            "Não comprova, por si, a eficácia ou ineficácia geral do fluxo formal em outras unidades"
          ]
        },
        {
          "proposicao": "A auditoria citada no relatório constatou que o procedimento de mudança de pessoas não estava sendo aplicado em nenhuma situação de mudança de pessoal na unidade, inclusive na saída dos superintendentes de marinha.",
          "trechos": [
            "E3dfa8ba0ae5476a8:693:1391"
          ],
          "condicoes": [
            "Constatação de auditoria referente ao FPSO CDSM"
          ],
          "limites": [
            "O trecho não informa amostragem, período exato nem extensão para outras instalações"
          ]
        },
        {
          "proposicao": "O relatório aponta que a assunção de função de superintendente por operadores envolvia não apenas sobrecarga por acúmulo de funções, mas também necessidade de avaliar competência e habilitações, já que avaliações de desempenho indicavam potencial para funções superiores enquanto também registravam ausência de licenças e certificados para promoção ao cargo de superintendente.",
          "trechos": [
            "E3dfa8ba0ae5476a8:1391:2083",
            "E3dfa8ba0ae5476a8:2083:2283"
          ],
          "condicoes": [
            "No contexto de promoção/assunção de função de superintendente de marinha no caso investigado"
          ],
          "limites": [
            "Conclusão circunscrita aos profissionais e documentos avaliados",
            "O trecho não define matriz geral de competência para todas as funções marítimas"
          ]
        }
      ]
    },
    {
      "id": "E679aa5317133bae8",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "O resumo recomenda acompanhamento contínuo, na fase operacional, da conformidade entre parâmetros de processo e composição do fluido e os limites estabelecidos na fase de projeto, bem como disponibilidade de informações necessárias ao SGSO e a estudos técnicos.",
          "trechos": [
            "E679aa5317133bae8:0:700"
          ],
          "condicoes": [
            "Durante a fase operacional da unidade",
            "Em relação aos limites definidos na fase de projeto"
          ],
          "limites": [
            "Recomendação derivada da investigação",
            "O trecho não especifica quais parâmetros, periodicidade ou métodos de monitoramento"
          ]
        },
        {
          "proposicao": "É recomendado revisar os estudos de risco antes do início da operação para considerar mudanças implementadas e características da unidade construída, com participação de equipes de projeto, operação e, no caso de unidade afretada, fiscalização do concessionário; também se recomenda participação e aprovação do concessionário nos estudos de risco.",
          "trechos": [
            "E679aa5317133bae8:0:700",
            "E679aa5317133bae8:700:1396"
          ],
          "condicoes": [
            "Antes do início da operação",
            "Especialmente quando houver mudanças implementadas e diferenças entre projeto e unidade construída",
            "No caso de plataformas de produção afretadas"
          ],
          "limites": [
            "Recomendação para governança e integração de atores",
            "O trecho não define metodologia de revisão nem nível documental de evidência além de exigir que ela exista"
          ]
        },
        {
          "proposicao": "Para mudanças temporárias, o resumo recomenda planejar ações até o retorno à condição definitiva e registrar esse planejamento no processo de gerenciamento de mudanças; recomenda ainda reavaliar o processo se houver alteração de premissas, escopo, finalidade ou planejamento, e estruturar passagem de serviço com conhecimento de mudanças, isolamentos e condições operacionais.",
          "trechos": [
            "E679aa5317133bae8:1396:2089",
            "E679aa5317133bae8:2089:2301"
          ],
          "condicoes": [
            "Aplicável a mudanças temporárias",
            "Quando houver alteração de premissas, escopo, finalidade ou planejamento",
            "Antes da assunção do trabalho em cada função"
          ],
          "limites": [
            "Recomendação investigativa; não detalha formatos, responsabilidades completas ou critérios de encerramento da mudança temporária"
          ]
        }
      ]
    },
    {
      "id": "E7ca947adbc364c38",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "O relatório final recomenda que, em unidades afretadas, a revisão dos estudos de risco seja evidenciada e conte com participação das equipes de projeto e operação, além da fiscalização do concessionário, e que o concessionário participe e aprove esses estudos em nível gerencial compatível com os recursos necessários.",
          "trechos": [
            "E7ca947adbc364c38:0:699"
          ],
          "condicoes": [
            "No contexto de plataformas de produção afretadas",
            "Em revisão de estudos de risco"
          ],
          "limites": [
            "Trata-se de recomendação do relatório final",
            "O trecho não transforma essa recomendação, por si só, em requisito geral fora do contexto regulatório aplicável"
          ]
        },
        {
          "proposicao": "Para mudanças temporárias, o relatório recomenda planejamento prévio até o retorno à condição definitiva do sistema e reavaliação do gerenciamento de mudanças quando se alterarem premissas, escopo, finalidade ou planejamento.",
          "trechos": [
            "E7ca947adbc364c38:699:1395"
          ],
          "condicoes": [
            "Antes da implementação de mudanças temporárias",
            "Quando houver alteração das condições originalmente consideradas"
          ],
          "limites": [
            "O trecho não define como comprovar retorno à condição definitiva nem critérios de aceitação das mudanças temporárias"
          ]
        },
        {
          "proposicao": "O relatório recomenda estruturar a passagem de serviço para assegurar conhecimento de mudanças, isolamentos e condições operacionais, manter documentação técnica fidedigna à condição de campo mesmo durante mudanças e garantir capacitação teórica e prática com reciclagem periódica para procedimentos de gerenciamento de mudanças.",
          "trechos": [
            "E7ca947adbc364c38:699:1395",
            "E7ca947adbc364c38:1395:2092",
            "E7ca947adbc364c38:2092:2387"
          ],
          "condicoes": [
            "Antes de assumir o trabalho a bordo",
            "Mesmo durante mudanças em equipamentos e processos"
          ],
          "limites": [
            "Recomendação abrangente, porém sem detalhamento de método, frequência, matriz de competência ou sistema documental específico"
          ]
        }
      ]
    }
